package blockbranch.realistic;
import java.util.*;
public final class WoodlandDetailsCheck{
 public static void main(String[]args){for(long seed:new long[]{424242,1,-17}){var d=new DrainageNetwork(new TerrainShape(seed),seed);var c=new ClimateField(seed);int logs=0,flowers=0,disturbed=0;var axes=new HashSet<Integer>();var points=new ArrayList<Forest.Point>();points.add(blockbranch.realistic.ForestFixtures.fixture(d,seed));var b=blockbranch.realistic.BirchForestFixtures.fixture(d,seed);points.add(new Forest.Point(b.x(),b.z()));
 for(var p:points){int cx=p.x()>>4,cz=p.z()>>4;for(int z=cz-8;z<=cz+8;z++)for(int x=cx-8;x<=cx+8;x++){var a=WoodlandDetails.temperateLogs(seed,x,z,d,c);if(!Arrays.equals(a,WoodlandDetails.temperateLogs(seed,x,z,d,c)))throw new AssertionError("World-coordinate chunk-order stability");for(int v:a){int key=v>>>blockbranch.cubic.CanopyLayer.STATE_BITS,wx=x*16+(key&15),wz=z*16+((key>>>4)&15),y=(key>>>8)+TerrainShape.FLOOR;var s=d.sample(wx,wz);if(y!=s.height()+1||s.waterLevel()!=DrainageNetwork.DRY||d.channelAt(wx,wz).edge()>=0||!Forest.potential(seed,wx,wz,d,c))throw new AssertionError("Dry supported habitat-qualified timber");logs++;axes.add(v&blockbranch.cubic.CanopyLayer.STATE_MASK);}}
 var dirt=new HashSet<Long>();var e=new GroundEcology.Field(d::sample,c);for(int dz=-96;dz<=96;dz++)for(int dx=-96;dx<=96;dx++){int x=p.x()+dx,z=p.z()+dz;var site=e.sample(x,z);int cover=Forest.cover(seed,x,z,site,true);if(cover>=30){flowers++;if(site.shaded()||site.wetness()<.4||site.wetness()>.8)throw new AssertionError("Appropriate sparse gap flowers");}if(cover==2){disturbed++;dirt.add((x&0xffffffffL)|((long)z<<32));}}
 while(!dirt.isEmpty()){var queue=new ArrayDeque<Long>();queue.add(dirt.iterator().next());int size=0;while(!queue.isEmpty()){long key=queue.removeFirst();if(!dirt.remove(key))continue;size++;int x=(int)key,z=(int)(key>>32);for(int[] q:new int[][]{{1,0},{-1,0},{0,1},{0,-1}}){long next=((x+q[0])&0xffffffffL)|((long)(z+q[1])<<32);if(dirt.contains(next))queue.add(next);}}if(size>64)throw new AssertionError("Oversized bare-ground patch "+size);}
}
 if(logs<5||flowers<5||disturbed<15||axes.size()<2)throw new AssertionError("Useful but varied actual detail witnesses "+logs+" "+flowers+" "+axes);System.out.println("WOODLAND_DETAILS seed="+seed+" logCells="+logs+" codes="+axes+" flowers="+flowers+" disturbance="+disturbed);}
 System.out.println("WOODLAND_DETAILS_SUPPORT_ORDER_SITE_PASS");}
}
